#[summary("ring buffer of at most 8 values")]
mod ring {
    #[invariant(in_bounds)]
    struct Ring { buf: [i64; 8], head: usize, len: usize }

    impl Ring {
        #[effects(pure)]
        #[uses(in_bounds)]
        fn get(self: &Ring, i: usize) -> Option<i64> {
            if i >= self.len {
                return None;
            }
            Some(self.buf[(self.head + i) % 8])
        }

        #[effects(pure)]
        #[uses(in_bounds)]
        fn new() -> Ring {
            Ring { buf: [0; 8], head: 0, len: 0 }
        }

        #[effects(pure)]
        #[uses(in_bounds)]
        fn pop(self: &mut Ring) -> Option<i64> {
            if self.len == 0 {
                return None;
            }
            let x: i64 = self.buf[self.head];
            self.head = (self.head + 1) % 8;
            self.len = self.len - 1;
            Some(x)
        }

        #[effects(pure)]
        #[uses(in_bounds)]
        fn push(self: &mut Ring, x: i64) -> bool {
            if self.len == 8 {
                return false;
            }
            self.buf[(self.head + self.len) % 8] = x;
            self.len = self.len + 1;
            true
        }

        #[effects(pure)]
        fn size(self: &Ring) -> usize {
            self.len
        }
    }

    spec fn in_bounds(r: &Ring) -> bool {
        r.head < 8 && r.len <= 8
    }

    #[effects(pure)]
    #[uses(in_bounds)]
    fn push_overwrite(r: &mut Ring, x: i64) -> Option<i64> {
        if r.len == 8 {
            let dropped: i64 = r.buf[r.head];
            r.buf[r.head] = x;
            r.head = (r.head + 1) % 8;
            Some(dropped)
        } else {
            r.buf[(r.head + r.len) % 8] = x;
            r.len = r.len + 1;
            None
        }
    }
}

